package com.wandertrace.service;
import com.wandertrace.exception.NotFoundException;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;
@Service public class ContentAccessService {private final JdbcTemplate db;public ContentAccessService(JdbcTemplate db){this.db=db;}public UUID tripForDestination(UUID destination){return uuid("select trip_id from destinations where id=?",destination,"Destination not found");}public UUID tripForMemory(UUID memory){return uuid("select d.trip_id from memories m join destinations d on d.id=m.destination_id where m.id=?",memory,"Memory not found");}public UUID memoryForMedia(UUID media){return uuid("select memory_id from media where id=?",media,"Media not found");}private UUID uuid(String sql,UUID id,String message){var rows=db.queryForList(sql,id);if(rows.isEmpty())throw new NotFoundException(message);return (UUID)rows.getFirst().values().iterator().next();}}
